/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path('Task.v');s=p.read_text(); st=s.index('Proof.',s.index('Lemma safety_wf_binding')); en=s.index('Qed.',st)
s=s[:st]+'''Proof.
  induction 1; intros y b Hb; [inversion Hb| | |];
    change (List.In (y,b) (_ :: _)) in Hb;
    destruct Hb as [Hb|Hb];
    [inversion Hb; subst | specialize (IHwf_env _ _ Hb); destruct b
    |inversion Hb; subst | specialize (IHwf_env _ _ Hb); destruct b
    |inversion Hb; subst | specialize (IHwf_env _ _ Hb); destruct b];
    eauto 6 with core_safety;
    (eapply safety_wf_typ_scope || eapply safety_wf_qtyp_scope ||
      eapply safety_wf_qua_scope); [eassumption|];
    apply safety_scopes_weaken; intros; right; assumption.
'''+s[en:];p.write_text(s)
PY
make -s 2>&1 | tail -20"

